__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_channels, int out_channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups, bool has_bias
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;

    const int total_output = batch_size * out_channels * out_h * out_w;
    if (idx >= total_output) return;

    const int oc = (idx / (out_h * out_w)) % out_channels;
    const int n = idx / (out_channels * out_h * out_w);
    const int oh = (idx / out_w) % out_h;
    const int ow = idx % out_w;

    const int group = oc / (out_channels / groups);
    const int in_ch_per_group = in_channels / groups;

    float sum = 0.0f;

    for (int ic = group * in_ch_per_group; ic < (group + 1) * in_ch_per_group; ++ic) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            for (int kw = 0; kw < kernel_w; ++kw) {
                const int ih = (oh - kh * dilation_h + padding_h) % stride_h;
                const int iw = (ow - kw * dilation_w + padding_w) % stride_w;
                if (ih != 0 || iw != 0) continue;

                const int input_h = (oh - kh * dilation_h + padding_h) / stride_h;
                const int input_w = (ow - kw * dilation_w + padding_w) / stride_w;

                if (input_h < 0 || input_h >= in_h || input_w < 0 || input_w >= in_w) continue;

                const int weight_idx = ic * (out_channels / groups) * kernel_h * kernel_w 
                                    + (oc % (out_channels / groups)) * kernel_h * kernel_w
                                    + kh * kernel_w + kw;

                sum += input[n * in_channels * in_h * in_w + ic * in_h * in_w + input_h * in_w + input_w]
                     * weight[weight_idx];
            }
        }
    }

    if (has_bias) sum += bias[oc];
    output[idx] = sum;
}

torch::Tensor conv_transpose2d_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups) {

    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_h = input.size(2);
    auto in_w = input.size(3);

    auto out_channels = weight.size(1) * groups;
    auto kernel_h = weight.size(2);
    auto kernel_w = weight.size(3);

    auto out_h = (in_h - 1) * stride_h - 2 * padding_h + dilation_h * (kernel_h - 1) + 1;
    auto out_w = (in_w - 1) * stride_w - 2 * padding_w + dilation_w * (kernel_w - 1) + 1;

    auto output = torch::empty({batch_size, out_channels, out_h, out_w}, input.options());

    int num_threads = 256;
    int total_elements = batch_size * out_channels * out_h * out_w;
    int num_blocks = (total_elements + num_threads - 1) / num_threads;

    hipStream_t stream = at::hip::getCurrentHIPStream();
    hipLaunchKernelGGL(
        conv_transpose2d_kernel,
        num_blocks, num_threads, 0, stream,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_h, in_w, out_h, out_w,
        kernel_h, kernel_w,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w,
        groups, bias.has_value()
    );

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
