#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void cosine_loss_kernel(const float* preds, const float* targets, float* output, int batch_size, int vector_size, float epsilon) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    const float* preds_batch = preds + batch_idx * vector_size;
    const float* targets_batch = targets + batch_idx * vector_size;

    float dot = 0.0f;
    float sum_p = 0.0f;
    float sum_t = 0.0f;

    for (int i = tid; i < vector_size; i += block_size) {
        float p = preds_batch[i];
        float t = targets_batch[i];
        dot += p * t;
        sum_p += p * p;
        sum_t += t * t;
    }

    __shared__ float sdot[256];
    __shared__ float ssum_p[256];
    __shared__ float ssum_t[256];

    sdot[tid] = dot;
    ssum_p[tid] = sum_p;
    ssum_t[tid] = sum_t;

    __syncthreads();

    for (int s = block_size/2; s > 0; s >>= 1) {
        if (tid < s) {
            sdot[tid] += sdot[tid + s];
            ssum_p[tid] += ssum_p[tid + s];
            ssum_t[tid] += ssum_t[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float sqrt_p = sqrtf(ssum_p[0] + epsilon);
        float sqrt_t = sqrtf(ssum_t[0] + epsilon);
        float cos_sim = sdot[0] / (sqrt_p * sqrt_t);
        output[batch_idx] = 1.0f - cos_sim;
    }
}

torch::Tensor cosine_loss_rocm(torch::Tensor preds, torch::Tensor targets) {
    TORCH_CHECK(preds.dim() == 2, "preds must be 2D");
    TORCH_CHECK(targets.dim() == 2, "targets must be 2D");
    TORCH_CHECK(preds.sizes() == targets.sizes(), "Input tensors must have same shape");

    int batch_size = preds.size(0);
    int vector_size = preds.size(1);
    float epsilon = 1e-8f;

    auto losses = torch::empty(batch_size, preds.options());
    const int block_size = 256;

    hipLaunchKernelGGL(cosine_loss_kernel, 
        dim3(batch_size), 
