__global__ void depthwise_conv2d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels,
    int input_h, int input_w,
    int output_h, int output_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int total_elements) {

    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index >= total_elements) return;

    // Unravel index into (n, c, h, w) components
    int n = index / (in_channels * output_h * output_w);
    int residual = index % (in_channels * output_h * output_w);
    int c = residual / (output_h * output_w);
    residual = residual % (output_h * output_w);
    int oh = residual / output_w;
    int ow = residual % output_w;

    float val = 0.0f;

    for(int kh = 0; kh < kernel_h; ++kh) {
        for(int kw = 0; kw < kernel_w; ++kw) {
            int ih = oh * stride_h - padding_h + kh * dilation_h;
            int iw = ow * stride_w - padding_w + kw * dilation_w;

            if(ih >= 0 && ih < input_h && iw >= 0 && iw < input_w) {
                int inp_idx = n * in_channels * input_h * input_w + c * input_h * input_w + ih * input_w + iw;
                int weight_idx = c * kernel_h * kernel_w + kh * kernel_w + kw;
                val += input[inp_idx] * weight[weight_idx];
            }
        }
    }

    if(bias != nullptr) {
        val += bias[c];
    }

    output[index] = val;
}

torch::Tensor depthwise_conv2d_rocm(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int stride_h, int stride_w, 
    int padding_h, int padding_w,
    int dilation_h, int dilation_w) {

    // Get input dimensions
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_h = input.size(2);
    int input_w = input.size(3);
    int kernel_h = weight.size(2);
    int kernel_w = weight.size(3);

    // Compute output dimensions
    int output_h = (input_h + 2*padding_h - dilation_h*(kernel_h-1) - 1) / stride_h + 1;
    int output_w = (input_w + 2*padding_w - dilation_w*(kernel_w-1) - 1) / stride_w + 1;

    // Create output tensor
    auto output = torch::zeros({batch_size, in_channels, output_h, output_w}, input.options());
    int total_elements = batch_size * in_channels * output_h * output_w;

    // Configure kernel launch parameters
    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    // Get current HIP stream
    hipStream_t stream = at::hip::getCurrentHIPStream().stream();

    // Launch kernel
    depthwise_conv2d_kernel<<<grid_size, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels,
